{
    "level": "A2",
    "intro": "У цій темі ти вивчиш <strong>основні правила утворення пасивного стану<\/strong>: базову формулу, як перетворювати активні речення на пасивні, та коли доречно використовувати пасив.",
    "rules": [
        {
            "label": "Формула",
            "color": "emerald",
            "text": "Базова структура пасиву: <strong>Subject + be + V3 (Past Participle)<\/strong>:",
            "example": "The cake is baked. — Торт випечений."
        },
        {
            "label": "Перетворення",
            "color": "blue",
            "text": "Object активного речення → Subject пасивного:",
            "example": "Tom writes letters. → Letters are written by Tom."
        },
        {
            "label": "Виконавець",
            "color": "rose",
            "text": "<strong>by + agent<\/strong> — вказує, хто виконує дію:",
            "example": "The book was written by Shakespeare."
        }
    ]
}

{
    "title": "1. Активний vs Пасивний стан",
    "intro": "Порівняння активного та пасивного стану:",
    "items": [
        {
            "label": "Active",
            "title": "Subject виконує дію",
            "subtitle": "Tom writes letters. — Том пише листи."
        },
        {
            "label": "Passive",
            "title": "Subject отримує дію",
            "subtitle": "Letters are written by Tom. — Листи пишуться Томом."
        },
        {
            "label": "Формула",
            "title": "be + V3",
            "subtitle": "Дієслово be у потрібному часі + Past Participle."
        },
        {
            "label": "Agent",
            "title": "by + виконавець",
            "subtitle": "Вказується, якщо важливо знати виконавця."
        }
    ]
}

{
    "title": "2. Як перетворити Active → Passive?",
    "sections": [
        {
            "label": "Крок 1",
            "color": "emerald",
            "description": "<strong>Object<\/strong> активного речення стає <strong>Subject<\/strong> пасивного:",
            "examples": [
                {
                    "en": "Active: Tom writes letters.",
                    "ua": "letters → Letters (стає підметом)"
                },
                {
                    "en": "Active: They built a house.",
                    "ua": "a house → A house (стає підметом)"
                }
            ]
        },
        {
            "label": "Крок 2",
            "color": "blue",
            "description": "Додаємо <strong>be<\/strong> у відповідному часі + <strong>V3<\/strong>:",
            "examples": [
                {
                    "en": "writes → is\/are written",
                    "ua": "Present Simple: am\/is\/are + V3"
                },
                {
                    "en": "built → was\/were built",
                    "ua": "Past Simple: was\/were + V3"
                }
            ]
        },
        {
            "label": "Крок 3",
            "color": "rose",
            "description": "<strong>Subject<\/strong> активного речення стає <strong>by + agent<\/strong> (за потреби):",
            "examples": [
                {
                    "en": "Tom → by Tom",
                    "ua": "Якщо важливо, хто виконує дію"
                },
                {
                    "en": "They → (пропускається)",
                    "ua": "Якщо виконавець невідомий або неважливий"
                }
            ]
        }
    ]
}

{
    "title": "3. Приклади перетворення Active → Passive",
    "intro": "Повний процес перетворення активних речень на пасивні:",
    "rows": [
        {
            "en": "Active: Mary bakes a cake.",
            "ua": "Марія печe торт.",
            "note": "→ Passive: A cake is baked by Mary."
        },
        {
            "en": "Active: They speak English here.",
            "ua": "Тут розмовляють англійською.",
            "note": "→ Passive: English is spoken here."
        },
        {
            "en": "Active: Someone stole my bike.",
            "ua": "Хтось вкрав мій велосипед.",
            "note": "→ Passive: My bike was stolen."
        },
        {
            "en": "Active: The company will hire new employees.",
            "ua": "Компанія найме нових працівників.",
            "note": "→ Passive: New employees will be hired by the company."
        }
    ],
    "warning": "📌 by + agent пропускається, якщо виконавець невідомий, неважливий або очевидний!"
}

{
    "title": "4. Коли використовувати пасивний стан?",
    "sections": [
        {
            "label": "Невідомий виконавець",
            "color": "emerald",
            "description": "Коли <strong>невідомо<\/strong>, хто виконав дію:",
            "examples": [
                {
                    "en": "My car was stolen last night.",
                    "ua": "Мою машину вкрали минулої ночі."
                },
                {
                    "en": "The window has been broken.",
                    "ua": "Вікно розбите."
                },
                {
                    "en": "The building was destroyed.",
                    "ua": "Будівля була зруйнована."
                }
            ]
        },
        {
            "label": "Неважливий виконавець",
            "color": "blue",
            "description": "Коли виконавець <strong>неважливий<\/strong> або очевидний:",
            "examples": [
                {
                    "en": "The streets are cleaned every day.",
                    "ua": "Вулиці прибираються щодня."
                },
                {
                    "en": "Tickets are sold at the entrance.",
                    "ua": "Квитки продаються біля входу."
                },
                {
                    "en": "The law was passed last year.",
                    "ua": "Закон був прийнятий минулого року."
                }
            ]
        },
        {
            "label": "Фокус на дії\/об'єкті",
            "color": "amber",
            "description": "Коли важливіша <strong>сама дія<\/strong> або <strong>об'єкт<\/strong>:",
            "examples": [
                {
                    "en": "The report was submitted on time.",
                    "ua": "Звіт був поданий вчасно."
                },
                {
                    "en": "The new system will be launched tomorrow.",
                    "ua": "Нова система буде запущена завтра."
                },
                {
                    "en": "The product is made in Germany.",
                    "ua": "Продукт виробляється в Німеччині."
                }
            ]
        },
        {
            "label": "Формальний стиль",
            "color": "rose",
            "description": "У <strong>науковому, офіційному<\/strong> та <strong>діловому<\/strong> стилі:",
            "examples": [
                {
                    "en": "The experiment was conducted carefully.",
                    "ua": "Експеримент був проведений ретельно."
                },
                {
                    "en": "Applicants will be notified by email.",
                    "ua": "Заявників повідомлять електронною поштою."
                },
                {
                    "en": "The data is analyzed weekly.",
                    "ua": "Дані аналізуються щотижня."
                }
            ]
        }
    ]
}

{
    "title": "5. By vs With у пасиві",
    "intro": "Різниця між <strong>by<\/strong> та <strong>with<\/strong> у пасивних реченнях:",
    "items": [
        {
            "label": "by",
            "title": "Хто виконує дію (agent)",
            "subtitle": "The book was written by Mark Twain."
        },
        {
            "label": "with",
            "title": "Чим\/за допомогою чого (instrument)",
            "subtitle": "The letter was written with a pen."
        },
        {
            "label": "by",
            "title": "Жива істота або організація",
            "subtitle": "The project was completed by our team."
        },
        {
            "label": "with",
            "title": "Інструмент, матеріал",
            "subtitle": "The cake was decorated with chocolate."
        }
    ]
}

{
    "title": "6. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Пропуск дієслова be.",
            "wrong": "The letter written yesterday.",
            "right": "✅ The letter was written yesterday."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Використання V1\/V2 замість V3.",
            "wrong": "English is speak here.",
            "right": "✅ English is spoken here."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Використання with замість by для виконавця.",
            "wrong": "The book was written with Shakespeare.",
            "right": "✅ The book was written by Shakespeare."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Зайвий by agent.",
            "wrong": "My car was stolen by someone.",
            "right": "✅ My car was stolen. (виконавець невідомий)"
        }
    ]
}

{
    "title": "Passive Basics",
    "items": [
        {
            "label": "Formation Rules — Правила утворення пасиву",
            "current": true
        },
        {
            "label": "Passive with Modal Verbs — Пасив з модальними",
            "current": false
        },
        {
            "label": "Causative — have/get something done",
            "current": false
        },
        {
            "label": "Get-Passive — Розмовний пасив",
            "current": false
        },
        {
            "label": "Impersonal Passive — Безособовий пасив",
            "current": false
        },
        {
            "label": "Negatives & Questions in Passive — Питання й заперечення",
            "current": false
        },
        {
            "label": "Phrasal Verbs in Passive — Фразові дієслова",
            "current": false
        },
        {
            "label": "Restrictions — Обмеження пасиву",
            "current": false
        },
        {
            "label": "Two-object Verbs in Passive — give/send/offer",
            "current": false
        },
        {
            "label": "Common Mistakes in Passive — Типові помилки",
            "current": false
        },
        {
            "label": "Formality & Style in Passive — Формальність і стиль",
            "current": false
        }
    ]
}

{
    "level": "B1",
    "intro": "У цій темі ти навчишся будувати <strong>заперечні та питальні речення<\/strong> у пасивному стані, а також давати <strong>короткі відповіді<\/strong> на yes\/no питання.",
    "rules": [
        {
            "label": "Заперечення",
            "color": "rose",
            "text": "Додаємо <strong>not<\/strong> після be:",
            "example": "The house isn't made of wood."
        },
        {
            "label": "Питання",
            "color": "blue",
            "text": "<strong>be<\/strong> виходить на перше місце:",
            "example": "Was it built in 1990?"
        },
        {
            "label": "Короткі відповіді",
            "color": "emerald",
            "text": "<strong>Yes\/No + subject + be<\/strong>:",
            "example": "Yes, it was. \/ No, it wasn't."
        }
    ]
}

{
    "title": "1. Заперечення в Present Simple Passive",
    "sections": [
        {
            "label": "Структура",
            "color": "rose",
            "description": "Формула: <strong>am\/is\/are + not + V3<\/strong>. Скорочені форми: <strong>isn't, aren't<\/strong>",
            "examples": [
                {
                    "en": "The products are not made in China.",
                    "ua": "Продукти не виробляються в Китаї."
                },
                {
                    "en": "This material isn't used anymore.",
                    "ua": "Цей матеріал більше не використовується."
                },
                {
                    "en": "I am not invited to the party.",
                    "ua": "Мене не запросили на вечірку."
                },
                {
                    "en": "The doors aren't locked at night.",
                    "ua": "Двері не замикаються на ніч."
                }
            ]
        },
        {
            "label": "Нюанси",
            "color": "amber",
            "description": "Форма <strong>am not<\/strong> не скорочується до \"amn't\". Використовуємо: <strong>I'm not<\/strong>",
            "examples": [
                {
                    "en": "I'm not included in the list.",
                    "ua": "Мене не включено до списку."
                }
            ]
        }
    ]
}

{
    "title": "2. Заперечення в Past Simple Passive",
    "sections": [
        {
            "label": "Структура",
            "color": "rose",
            "description": "Формула: <strong>was\/were + not + V3<\/strong>. Скорочені: <strong>wasn't, weren't<\/strong>",
            "examples": [
                {
                    "en": "The house was not built in 1990.",
                    "ua": "Будинок не був побудований у 1990."
                },
                {
                    "en": "The letter wasn't sent yesterday.",
                    "ua": "Лист не був надісланий вчора."
                },
                {
                    "en": "We were not informed about the changes.",
                    "ua": "Нас не повідомили про зміни."
                },
                {
                    "en": "The tickets weren't sold out.",
                    "ua": "Квитки не були розпродані."
                }
            ]
        }
    ]
}

{
    "title": "3. Заперечення в інших часах",
    "sections": [
        {
            "label": "Future Simple",
            "color": "rose",
            "description": "<strong>will not (won't) + be + V3<\/strong>",
            "examples": [
                {
                    "en": "The project will not be finished on time.",
                    "ua": "Проєкт не буде завершено вчасно."
                },
                {
                    "en": "The meeting won't be held tomorrow.",
                    "ua": "Зустріч не відбудеться завтра."
                }
            ]
        },
        {
            "label": "Present Perfect",
            "color": "rose",
            "description": "<strong>has\/have + not + been + V3<\/strong>. Скорочені: <strong>hasn't, haven't<\/strong>",
            "examples": [
                {
                    "en": "The work has not been completed yet.",
                    "ua": "Робота ще не завершена."
                },
                {
                    "en": "The files haven't been uploaded.",
                    "ua": "Файли не були завантажені."
                }
            ]
        }
    ]
}

{
    "title": "4. Yes\/No питання в пасиві",
    "sections": [
        {
            "label": "Present Simple",
            "color": "blue",
            "description": "<strong>Am\/Is\/Are + S + V3?<\/strong>",
            "examples": [
                {
                    "en": "Is English spoken here?",
                    "ua": "Тут розмовляють англійською?"
                },
                {
                    "en": "Are the rooms cleaned daily?",
                    "ua": "Кімнати прибираються щодня?"
                },
                {
                    "en": "Am I included in the team?",
                    "ua": "Мене включено до команди?"
                }
            ]
        },
        {
            "label": "Past Simple",
            "color": "blue",
            "description": "<strong>Was\/Were + S + V3?<\/strong>",
            "examples": [
                {
                    "en": "Was the house built in 1990?",
                    "ua": "Будинок був побудований у 1990?"
                },
                {
                    "en": "Were the documents signed?",
                    "ua": "Документи були підписані?"
                }
            ]
        },
        {
            "label": "Future Simple",
            "color": "blue",
            "description": "<strong>Will + S + be + V3?<\/strong>",
            "examples": [
                {
                    "en": "Will the project be finished on time?",
                    "ua": "Проєкт буде завершено вчасно?"
                },
                {
                    "en": "Will you be invited to the meeting?",
                    "ua": "Тебе запросять на зустріч?"
                }
            ]
        },
        {
            "label": "Present Perfect",
            "color": "blue",
            "description": "<strong>Has\/Have + S + been + V3?<\/strong>",
            "examples": [
                {
                    "en": "Has the work been completed?",
                    "ua": "Роботу завершено?"
                },
                {
                    "en": "Have the tickets been sold?",
                    "ua": "Квитки продано?"
                }
            ]
        }
    ]
}

{
    "title": "5. Короткі відповіді (Short Answers)",
    "sections": [
        {
            "label": "Правило",
            "color": "emerald",
            "description": "Структура: <strong>Yes\/No + subject pronoun + be (у тому ж часі)<\/strong>",
            "examples": [
                {
                    "en": "Is the door locked? — Yes, it is. \/ No, it isn't.",
                    "ua": "Двері замкнені? — Так. \/ Ні."
                },
                {
                    "en": "Was the letter sent? — Yes, it was. \/ No, it wasn't.",
                    "ua": "Лист надіслано? — Так. \/ Ні."
                },
                {
                    "en": "Are they invited? — Yes, they are. \/ No, they aren't.",
                    "ua": "Їх запросили? — Так. \/ Ні."
                }
            ]
        },
        {
            "label": "Present Perfect",
            "color": "emerald",
            "description": "У Present Perfect: <strong>Yes\/No + S + has\/have<\/strong>",
            "examples": [
                {
                    "en": "Has the work been finished? — Yes, it has. \/ No, it hasn't.",
                    "ua": "Роботу закінчено? — Так. \/ Ні."
                },
                {
                    "en": "Have they been informed? — Yes, they have. \/ No, they haven't.",
                    "ua": "Їх повідомили? — Так. \/ Ні."
                }
            ]
        },
        {
            "label": "Future Simple",
            "color": "emerald",
            "description": "У Future: <strong>Yes\/No + S + will\/won't<\/strong>",
            "examples": [
                {
                    "en": "Will it be done tomorrow? — Yes, it will. \/ No, it won't.",
                    "ua": "Це буде зроблено завтра? — Так. \/ Ні."
                }
            ]
        }
    ]
}

{
    "title": "6. Wh-питання в пасиві",
    "sections": [
        {
            "label": "Структура",
            "color": "sky",
            "description": "<strong>Wh-word + be + S + V3?<\/strong>",
            "examples": [
                {
                    "en": "Where is coffee grown?",
                    "ua": "Де вирощують каву?"
                },
                {
                    "en": "When was the house built?",
                    "ua": "Коли був побудований будинок?"
                },
                {
                    "en": "How are these products made?",
                    "ua": "Як виробляються ці продукти?"
                },
                {
                    "en": "Why was the meeting cancelled?",
                    "ua": "Чому зустріч скасували?"
                }
            ]
        },
        {
            "label": "Who\/What як підмет",
            "color": "sky",
            "description": "Коли питальне слово — підмет: <strong>Who\/What + be + V3?<\/strong> (без інверсії)",
            "examples": [
                {
                    "en": "What is produced here?",
                    "ua": "Що тут виробляється?"
                },
                {
                    "en": "Who was invited to the party?",
                    "ua": "Кого запросили на вечірку?"
                }
            ]
        }
    ]
}

{
    "title": "7. Зведена таблиця питань та заперечень",
    "intro": "Основні структури заперечень та питань у різних часах:",
    "rows": [
        {
            "en": "Present Simple",
            "ua": "It isn't made here.",
            "note": "Is it made here? — Yes, it is. \/ No, it isn't."
        },
        {
            "en": "Past Simple",
            "ua": "It wasn't built in 1990.",
            "note": "Was it built in 1990? — Yes, it was. \/ No, it wasn't."
        },
        {
            "en": "Future Simple",
            "ua": "It won't be finished.",
            "note": "Will it be finished? — Yes, it will. \/ No, it won't."
        },
        {
            "en": "Present Perfect",
            "ua": "It hasn't been done.",
            "note": "Has it been done? — Yes, it has. \/ No, it hasn't."
        }
    ]
}

{
    "title": "8. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Неправильний порядок слів у питанні.",
            "wrong": "The house was built in 1990?",
            "right": "✅ Was the house built in 1990?"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Пропуск допоміжного дієслова в питанні.",
            "wrong": "It made in China?",
            "right": "✅ Is it made in China?"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Неповна коротка відповідь.",
            "wrong": "Was it built? — Yes, it.",
            "right": "✅ Yes, it was."
        }
    ]
}

{
    "title": "9. Короткий конспект",
    "items": [
        "Заперечення: <strong>be + not + V3<\/strong> (isn't, wasn't, won't be, hasn't been).",
        "Yes\/No питання: <strong>be<\/strong> виходить на перше місце перед підметом.",
        "Короткі відповіді: <strong>Yes\/No + subject + be<\/strong> (у тому ж часі).",
        "Wh-питання: <strong>Wh-word + be + S + V3?<\/strong>",
        "Коли Who\/What — підмет, інверсія не потрібна: <strong>What is produced?<\/strong>"
    ]
}

{
    "title": "Passive Basics",
    "items": [
        {
            "label": "Formation Rules — Правила утворення пасиву",
            "current": false
        },
        {
            "label": "Passive with Modal Verbs — Пасив з модальними",
            "current": false
        },
        {
            "label": "Causative — have/get something done",
            "current": false
        },
        {
            "label": "Get-Passive — Розмовний пасив",
            "current": false
        },
        {
            "label": "Impersonal Passive — Безособовий пасив",
            "current": false
        },
        {
            "label": "Negatives & Questions in Passive — Питання й заперечення",
            "current": true
        },
        {
            "label": "Phrasal Verbs in Passive — Фразові дієслова",
            "current": false
        },
        {
            "label": "Restrictions — Обмеження пасиву",
            "current": false
